create table if not exists public.legal_documents (id uuid primary key default gen_random_uuid(), slug text not null, version text not null, title text not null, body text not null, published_at timestamptz not null default now(), active boolean not null default true, unique(slug,version));
create table if not exists public.user_consents (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, legal_document_id uuid not null references public.legal_documents(id), accepted_at timestamptz not null default now(), user_agent text, metadata jsonb not null default '{}'::jsonb, unique(user_id,legal_document_id));
alter table public.legal_documents enable row level security; alter table public.user_consents enable row level security;
drop policy if exists legal_public_read on public.legal_documents; create policy legal_public_read on public.legal_documents for select using(active=true);
drop policy if exists consent_self on public.user_consents; create policy consent_self on public.user_consents for select using(user_id=auth.uid());
drop policy if exists consent_insert_self on public.user_consents; create policy consent_insert_self on public.user_consents for insert with check(user_id=auth.uid());
insert into public.legal_documents(slug,version,title,body) values ('terms','1.0','Términos y consentimiento de IDsanna','La navegación y los MCP solo pueden realizar acciones de escritura, publicación, mensajería o interacción con páginas después de una confirmación específica del usuario. Las respuestas de IA deben verificarse y el usuario conserva la responsabilidad por sus archivos.') on conflict(slug,version) do nothing;
